<?php
require_once __DIR__.'/include/config.php'; require_once __DIR__.'/../include/billing.php';
hms_start_session(); hms_require_role('admin'); $ready=hms_billing_ready($con); $error='';
if ($ready && $_SERVER['REQUEST_METHOD']==='POST') { hms_verify_csrf(); $started=false;
 try { $action=hms_post_string('action',20);
  if ($action==='create') { $token=(string)($_POST['request_token']??''); if($token===''||!hash_equals((string)($_SESSION['billing_create_token']??''),$token)) throw new InvalidArgumentException('This invoice form has already been submitted. Reload the page to create another invoice.'); unset($_SESSION['billing_create_token']);
   $patient=filter_var($_POST['patient_user_id']??null,FILTER_VALIDATE_INT); $due=hms_post_string('due_date',10); $discount=filter_var($_POST['discount']??'0',FILTER_VALIDATE_FLOAT); $tax=filter_var($_POST['tax']??'0',FILTER_VALIDATE_FLOAT); $descriptions=$_POST['description']??[]; $quantities=$_POST['quantity']??[]; $prices=$_POST['unit_price']??[];
   if(!$patient||!is_array($descriptions)||count($descriptions)<1||count($descriptions)>12||$discount===false||$tax===false||$discount<0||$tax<0) throw new InvalidArgumentException('Enter a patient, one to twelve valid charges, discount, and tax.');
   if(!hms_db_query($con,'SELECT id FROM users WHERE id=?',[$patient])->num_rows) throw new InvalidArgumentException('The selected patient was not found.');
   $con->begin_transaction(); $started=true; $number='MTB-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));
   hms_db_query($con,'INSERT INTO billing_invoices(invoice_number,patient_user_id,issue_date,due_date,discount_amount,tax_amount,created_by_admin_id) VALUES(?,?,CURDATE(),?,?,?,?)',[$number,$patient,$due?:null,$discount,$tax,(int)$_SESSION['id']]); $invoiceId=(int)$con->insert_id;
   foreach($descriptions as $key=>$description){$description=trim((string)$description);$quantity=filter_var($quantities[$key]??null,FILTER_VALIDATE_FLOAT);$price=filter_var($prices[$key]??null,FILTER_VALIDATE_FLOAT);if($description===''||strlen($description)>255||$quantity===false||$quantity<=0||$price===false||$price<0)throw new InvalidArgumentException('Every charge needs a description, positive quantity, and price.');hms_db_query($con,'INSERT INTO billing_invoice_items(invoice_id,description,quantity,unit_price,line_total) VALUES(?,?,?,?,?)',[$invoiceId,$description,$quantity,$price,$quantity*$price]);}
   hms_billing_refresh($con,$invoiceId); $con->commit(); $started=false; header('Location: invoice.php?id='.$invoiceId); exit;
  }
  if ($action==='payment') { $invoiceId=filter_var($_POST['invoice_id']??null,FILTER_VALIDATE_INT);$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);$method=hms_post_string('payment_method',30);$reference=hms_post_string('reference',120);if(!$invoiceId||$amount===false||$amount<=0||!in_array($method,['cash','card','upi','bank_transfer','insurance'],true))throw new InvalidArgumentException('Enter a valid payment amount and method.');$con->begin_transaction();$started=true;$invoice=hms_db_query($con,'SELECT balance_amount,status FROM billing_invoices WHERE id=? FOR UPDATE',[$invoiceId])->fetch_assoc();if(!$invoice||in_array($invoice['status'],['paid','cancelled'],true)||$amount>(float)$invoice['balance_amount'])throw new InvalidArgumentException('This payment exceeds the outstanding balance or cannot be recorded.');$receipt='MTR-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));hms_db_query($con,'INSERT INTO billing_payments(receipt_number,invoice_id,amount,payment_method,transaction_reference,received_by_admin_id) VALUES(?,?,?,?,?,?)',[$receipt,$invoiceId,$amount,$method,$reference?:null,(int)$_SESSION['id']]);hms_billing_refresh($con,$invoiceId);$con->commit();$started=false;header('Location: invoice.php?id='.$invoiceId.'&receipt='.rawurlencode($receipt));exit;
  }
  throw new InvalidArgumentException('Unknown billing action.');
 } catch(Throwable $e){if($started)$con->rollback();error_log('HMS billing write failed: '.$e->getMessage());$error=$e instanceof InvalidArgumentException?$e->getMessage():'The billing request could not be saved.';}
}
if(empty($_SESSION['billing_create_token']))$_SESSION['billing_create_token']=bin2hex(random_bytes(24)); $formToken=$_SESSION['billing_create_token'];$query=trim((string)($_GET['q']??''));if(strlen($query)>100)$query='';$patients=$ready?hms_db_query($con,'SELECT id,fullName FROM users ORDER BY fullName'):null;$sql='SELECT i.*,u.fullName patient FROM billing_invoices i JOIN users u ON u.id=i.patient_user_id';$params=[];if($query!==''){$sql.=' WHERE i.invoice_number LIKE ? OR u.fullName LIKE ? OR i.status=?';$params=['%'.$query.'%','%'.$query.'%',$query];}$sql.=' ORDER BY i.id DESC';$rows=$ready?hms_db_query($con,$sql,$params):null;
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Billing · MedTech</title><link rel="stylesheet" href="vendor/bootstrap/css/bootstrap.min.css"></head><body><div id="app"><?php include 'include/sidebar.php';?><div class="app-content"><?php include 'include/header.php';?><main class="container"><h1>Billing &amp; invoices</h1><?php if(!$ready):?><div class="alert alert-warning"><?=hms_h(hms_billing_notice())?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=hms_h($error)?></div><?php endif;?><form method="get"><input name="q" value="<?=hms_h($query)?>" placeholder="Patient, invoice, or status"><button class="btn btn-default">Search</button></form><div class="row"><section class="col-md-8"><table class="table"><tr><th>Invoice</th><th>Patient</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th></tr><?php if($rows)while($row=$rows->fetch_assoc()):?><tr><td><a href="invoice.php?id=<?=hms_h($row['id'])?>"><?=hms_h($row['invoice_number'])?></a></td><td><?=hms_h($row['patient'])?></td><td>₹<?=number_format((float)$row['total_amount'],2)?></td><td>₹<?=number_format((float)$row['amount_paid'],2)?></td><td>₹<?=number_format((float)$row['balance_amount'],2)?></td><td><?=hms_h($row['status'])?></td></tr><?php endwhile;?></table></section><?php if($ready):?><aside class="col-md-4"><form method="post"><?=hms_csrf_field()?><input type="hidden" name="action" value="create"><input type="hidden" name="request_token" value="<?=hms_h($formToken)?>"><h2>New invoice</h2><select class="form-control" name="patient_user_id" required><option value="">Choose patient</option><?php while($patient=$patients->fetch_assoc()):?><option value="<?=hms_h($patient['id'])?>"><?=hms_h($patient['fullName'])?></option><?php endwhile;?></select><input class="form-control" type="date" name="due_date"><div id="billing-items"><p><input class="form-control" name="description[]" placeholder="Charge description" required><input name="quantity[]" type="number" min=".01" step=".01" value="1" required><input name="unit_price[]" type="number" min="0" step=".01" placeholder="Unit price" required></p></div><button type="button" class="btn btn-default" onclick="addItem()">Add line</button><input class="form-control" name="discount" value="0" type="number" min="0" step=".01" placeholder="Discount"><input class="form-control" name="tax" value="0" type="number" min="0" step=".01" placeholder="Tax"><button class="btn btn-primary">Create invoice</button></form></aside><?php endif;?></div></main></div></div><script>function addItem(){if(document.querySelectorAll('#billing-items p').length<12)document.querySelector('#billing-items').insertAdjacentHTML('beforeend','<p><input class="form-control" name="description[]" placeholder="Charge description" required><input name="quantity[]" type="number" min=".01" step=".01" value="1" required><input name="unit_price[]" type="number" min="0" step=".01" placeholder="Unit price" required></p>')}</script></body></html>
